import{_ as o,o as l,c as r,ah as n}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"2권 1장 원문 번역 — 성격의 탁월함은 습관화의 산물이다","slug":"_2권-1장-원문-번역-—-성격의-탁월함은-습관화의-산물이다","link":"#_2권-1장-원문-번역-—-성격의-탁월함은-습관화의-산물이다","children":[{"level":3,"title":"내가 가졌던 의문과 그 해소","slug":"내가-가졌던-의문과-그-해소","link":"#내가-가졌던-의문과-그-해소","children":[]}]},{"level":2,"title":"오늘 강의 개요 (3주차)","slug":"오늘-강의-개요-3주차","link":"#오늘-강의-개요-3주차","children":[]},{"level":2,"title":"『니코마코스 윤리학』이라는 제목","slug":"『니코마코스-윤리학』이라는-제목","link":"#『니코마코스-윤리학』이라는-제목","children":[]},{"level":2,"title":"윤리학과 정치학의 관계 — 왜 아리스토텔레스는 둘을 분리하지 않는가","slug":"윤리학과-정치학의-관계-—-왜-아리스토텔레스는-둘을-분리하지-않는가","link":"#윤리학과-정치학의-관계-—-왜-아리스토텔레스는-둘을-분리하지-않는가","children":[{"level":3,"title":"현대적 적용 — 소셜미디어 플랫폼이라는 \\"정치 공동체 아닌 정치 공동체\\"","slug":"현대적-적용-—-소셜미디어-플랫폼이라는-정치-공동체-아닌-정치-공동체","link":"#현대적-적용-—-소셜미디어-플랫폼이라는-정치-공동체-아닌-정치-공동체","children":[]},{"level":3,"title":"AI와 목적론 — 수단과 목적의 구분","slug":"ai와-목적론-—-수단과-목적의-구분","link":"#ai와-목적론-—-수단과-목적의-구분","children":[]}]},{"level":2,"title":"습관화(habituation) 도입 — 지적 탁월함 vs 성격의 탁월함","slug":"습관화-habituation-도입-—-지적-탁월함-vs-성격의-탁월함","link":"#습관화-habituation-도입-—-지적-탁월함-vs-성격의-탁월함","children":[{"level":3,"title":"지적 탁월함이 가르침만으로 부족한 이유 — 경험과 시간","slug":"지적-탁월함이-가르침만으로-부족한-이유-—-경험과-시간","link":"#지적-탁월함이-가르침만으로-부족한-이유-—-경험과-시간","children":[]}]},{"level":2,"title":"소크라테스적 주지주의 비판 — 앎이 곧 행동을 보장하지 않는다","slug":"소크라테스적-주지주의-비판-—-앎이-곧-행동을-보장하지-않는다","link":"#소크라테스적-주지주의-비판-—-앎이-곧-행동을-보장하지-않는다","children":[]},{"level":2,"title":"2권 1장 정독 — 4가지 질문을 염두에 두고 읽기","slug":"_2권-1장-정독-—-4가지-질문을-염두에-두고-읽기","link":"#_2권-1장-정독-—-4가지-질문을-염두에-두고-읽기","children":[{"level":3,"title":"지성 vs 성격 — 영혼의 두 차원","slug":"지성-vs-성격-—-영혼의-두-차원","link":"#지성-vs-성격-—-영혼의-두-차원","children":[]},{"level":3,"title":"습관화의 기본 메커니즘","slug":"습관화의-기본-메커니즘","link":"#습관화의-기본-메커니즘","children":[]},{"level":3,"title":"\\"본성에 의해서도, 본성에 반해서도 아니다\\" — 돌/불 사례의 정밀 해석","slug":"본성에-의해서도-본성에-반해서도-아니다-—-돌-불-사례의-정밀-해석","link":"#본성에-의해서도-본성에-반해서도-아니다-—-돌-불-사례의-정밀-해석","children":[]},{"level":3,"title":"내가 가졌던 의문 (돌 사례 재확인)","slug":"내가-가졌던-의문-돌-사례-재확인","link":"#내가-가졌던-의문-돌-사례-재확인","children":[]}]}],"relativePath":"philosophy/Ethics/04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치.md","filePath":"philosophy/Ethics/04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치.md"}'),i={name:"philosophy/Ethics/04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치.md"};function s(e,t,a,u,g,h){return l(),r("div",null,[...t[0]||(t[0]=[n('<h2 id="_2권-1장-원문-번역-—-성격의-탁월함은-습관화의-산물이다" tabindex="-1">2권 1장 원문 번역 — 성격의 탁월함은 습관화의 산물이다 <a class="header-anchor" href="#_2권-1장-원문-번역-—-성격의-탁월함은-습관화의-산물이다" aria-label="Permalink to &quot;2권 1장 원문 번역 — 성격의 탁월함은 습관화의 산물이다&quot;">​</a></h2><blockquote><p><strong>탁월함(excellence)에는 두 종류가 있다.</strong> 하나는 지적인 것이고 다른 하나는 성격(인격)에 관한 것이다. 지적인 종류의 탁월함은 대부분 가르침을 통해 생겨나고 성장한다(그래서 그것은 경험과 시간을 필요로 한다). 반면 <strong>성격의 탁월함은 습관화(habituation)의 결과로 생긴다</strong> — 이것이 실제로 &quot;성격(ēthikē)&quot;이라는 이름의 유래이며, 이 단어는 &quot;습관화(ethos)&quot;를 뜻하는 단어에서 약간 변형된 것이다.</p><p>이로부터 성격의 탁월함들 중 어느 것도 <strong>본성적으로(by nature)</strong> 우리 안에 생겨나는 것이 아님이 분명해진다. 왜냐하면 본성적으로 어떤 한 방식으로 움직이는 것은 습관을 통해 다른 방식으로 바뀔 수 없기 때문이다 — 예컨대 본성적으로 아래로 움직이는 돌은, 누군가 그것을 만 번 위로 던져 습관을 들이려 해도 위로 움직이도록 습관화될 수 없고, 불이 아래로 움직이도록 습관화될 수 없으며, 본성적으로 어떤 한 방식으로 존재하는 다른 어떤 것도 다른 방식으로 행동하도록 습관화될 수 없다.</p><p>그러므로 탁월함들은 우리 안에서 <strong>본성에 의해서도, 본성에 반해서도 생겨나는 것이 아니라</strong>, 우리가 본성적으로 그것들을 받아들일 능력을 지니고 있고, 습관화를 통해 완성에 이르게 되는 것이다.</p><p>또한, 본성적으로 우리에게 주어지는 것들의 경우, 우리는 먼저 그것들에 대한 능력(capacity)을 지니고, 나중에 그것을 실제로 발휘한다(이는 감각의 경우에서 분명히 드러난다 — 우리는 반복해서 보거나 반복해서 들음으로써 감각을 획득한 것이 아니라, 오히려 그 반대다 — 우리는 감각을 가졌기 때문에 그것을 사용했지, 사용했기 때문에 획득한 것이 아니다). 반면 <strong>우리는 탁월함들을, 먼저 그 활동들에 관여함으로써 획득한다</strong> — 이는 여러 종류의 전문적 지식의 경우도 마찬가지다. 왜냐하면 우리가 마땅히 해야 할 일들을, 그것을 하는 법을 아는 것은, 바로 그것들을 행함으로써 배우는 것이기 때문이다.</p><p>예를 들어 사람들은 <strong>집을 지음으로써 건축가가 되고, 키타라(현악기)를 연주함으로써 키타라 연주자가 된다.</strong> 마찬가지로 <strong>우리는 정의로운 일들을 행함으로써 정의로워지고, 절제 있는 일들을 행함으로써 절제하게 되며, 용감한 일들을 행함으로써 용감해진다.</strong></p><p>도시들에서 일어나는 일이 이를 증언한다: 입법자들은 습관화를 통해 시민들을 선하게 만들며, 이것이 모든 입법자가 목표로 하는 것이지만, 그것을 서투르게 하는 자들은 그 목표를 빗나간다 — 그리고 바로 이 점이 좋은 정체(constitution)와 나쁜 정체를 구별 짓는 것이다.</p><p>또한, <strong>모든 탁월함은 그것이 생겨나는 것과 동일한 것들로부터, 그리고 동일한 것들을 통해 파괴되기도 한다</strong> — 이는 모든 전문 기술도 마찬가지다. 왜냐하면 좋은 키타라 연주자도 나쁜 키타라 연주자도 모두 키타라를 연주함으로써 생겨나기 때문이다. 건축가들과 다른 이들도 마찬가지다 — 좋은 건축은 좋은 건축가를 낳고, 나쁜 건축은 나쁜 건축가를 낳는다. 만약 그렇지 않다면, 누군가 그들을 가르칠 필요가 전혀 없을 것이고, 모두가 그냥 저절로 좋은 건축가나 나쁜 건축가가 되었을 것이다.</p><p>탁월함들도 바로 이와 같다. 왜냐하면 우리가 인간들과의 관계 속에서 행동하는 방식을 통해, 우리 중 일부는 정의로워지고 다른 일부는 불의해지며, 두려운 상황 속에서 행동하는 방식과 두려워하거나 (자신감을 갖는 방식을) 습관화됨으로써 ... (다음 쪽으로 이어짐)</p></blockquote><p><strong>요지</strong>: 성격의 탁월함(덕)은 타고나는 것이 아니라 <strong>반복된 실천(습관화)을 통해 형성</strong>된다 — 건축가가 집을 지어봄으로써 건축가가 되듯, 정의로운 행동을 해봄으로써 정의로워지고 용감한 행동을 해봄으로써 용감해진다. 같은 활동을 통해 탁월함이 만들어지기도 하고 파괴되기도 한다는 점(잘 연주하면 좋은 연주자가, 잘못 연주하면 나쁜 연주자가 되듯)도 핵심.</p><p><strong>주의</strong>: &quot;지적 탁월함(가르침) vs 성격의 탁월함(습관화)&quot; 구분에서, &quot;본성으로 생기는 게 아니다&quot;라는 논증은 <strong>성격의 탁월함에만</strong> 명시적으로 적용된다. 지적 탁월함 쪽은 &quot;가르침 + 시간이 필요하다&quot;고만 하고, 본성 여부에 대한 별도 논증은 펴지 않는다.</p><h3 id="내가-가졌던-의문과-그-해소" tabindex="-1">내가 가졌던 의문과 그 해소 <a class="header-anchor" href="#내가-가졌던-의문과-그-해소" aria-label="Permalink to &quot;내가 가졌던 의문과 그 해소&quot;">​</a></h3><blockquote><p><strong>의문</strong>: 돌이 본성상 아래로만 움직여서 위로 습관화될 수 없다는 게, 만약 어떤 것이 &quot;본성&quot;이라면 습관화로 영원히 안 바뀐다는 뜻 아닌가? 그럼 성격도 본성이라면 똑같이 영원히 안 바뀌어야 하는 거 아닌가?</p></blockquote><p><strong>해소</strong>: 이 직관이 정확히 아리스토텔레스 논증의 구조다. 돌 사례는 &quot;본성으로 고정된 것 = 습관화가 원리상 불가능함&quot;을 보여주는 대조 사례로 쓰인다. 그런데 우리는 경험적으로 <strong>인간의 성격은 습관화로 실제 바뀐다</strong>는 걸 안다(정의로운 행동을 반복하면 실제로 정의로워짐). 만약 성격도 돌처럼 본성으로 고정된 것이라면 돌이 위로 못 움직이듯 절대 안 바뀌어야 하는데, 실제로는 바뀌므로 — <strong>귀류법적으로</strong> &quot;성격의 탁월함은 돌의 낙하운동처럼 본성으로 고정된 것이 아니다&quot;라고 결론 내리는 것.</p><p>다만 완전히 &quot;본성과 무관&quot;한 것도 아니라서, 아리스토텔레스는 &quot;본성에 의해서도, 본성에 반해서도 아니다&quot;라고 쓴다 — 우리는 <strong>본성적으로 그것을 받아들일 능력(capacity)</strong>은 갖고 태어나지만, 그 능력이 정의로운 방향으로 굳어질지 불의한 방향으로 굳어질지는 <strong>어떤 행동을 반복하느냐(습관화)</strong>에 달려 있다. 능력=타고남, 실제 성격=습관화의 결과로 나눠보면 논리적 모순이 풀린다.</p><h2 id="오늘-강의-개요-3주차" tabindex="-1">오늘 강의 개요 (3주차) <a class="header-anchor" href="#오늘-강의-개요-3주차" aria-label="Permalink to &quot;오늘 강의 개요 (3주차)&quot;">​</a></h2><p>지난 시간(2주차)에 &quot;행복은 덕에 따른 영혼의 활동&quot;이라는 결론에 도달했다면, 이번 시간은 그 결론이 남긴 질문에서 출발한다: <strong>행복이 덕을 필요로 한다면, 사람들은 어떻게 덕을 갖추게 되는가?</strong> 용기와 지혜는 타고난 능력인가, 아니면 학습과 습관화를 통해 획득한 성격 특성인가? 윤리 이론을 읽는 것만으로 도덕적으로 선한 사람이 될 수 있는가 — 즉 옳은 것을 아는 것이 옳은 행동을 보장하는가?</p><p>오늘 강의는 5부로 구성:</p><ol><li>『니코마코스 윤리학』이라는 제목에 대하여</li><li>윤리학과 정치학의 관계</li><li>습관화(habituation)</li><li>중용(the doctrine of the mean)</li><li>선택과 실천적 지혜</li></ol><p><em>(강의 중간에 TransLive 세션이 한 차례 끊겼다가 재연결됨 — 1~3부까지는 확보되었고, 4부(중용)·5부(선택과 실천적 지혜)는 다음 자료로 보강 예정.)</em></p><h2 id="『니코마코스-윤리학』이라는-제목" tabindex="-1">『니코마코스 윤리학』이라는 제목 <a class="header-anchor" href="#『니코마코스-윤리학』이라는-제목" aria-label="Permalink to &quot;『니코마코스 윤리학』이라는 제목&quot;">​</a></h2><ul><li>전통적 그리스어 제목은 <strong>Ethika Nikomacheia</strong>. &quot;니코마코스&quot;라는 이름의 정확한 유래는 불확실하다 — 아리스토텔레스의 아들 이름도, 아버지 이름도 니코마코스였다. 아들이 자료를 편집·전달했기 때문이라는 설과, 아버지를 기리기 위해서라는 설이 있으나 확정할 증거는 없다.</li><li>이 책은 현대 입문서처럼 쓰이지 않았다 — <strong>짧고 압축된 논증</strong>을 사용하며, 완전한 정의를 내리기 전에 개념을 먼저 소개하고, 한 권에서 질문을 제기한 뒤 나중에 다시 돌아오는 방식이다. <ul><li>예: 1권은 덕 있는 활동을 통해 행복을 정의, 2권은 덕이 어떻게 획득되는지, 3권은 의도적 선택, 6권은 실천적 지혜, 8·9권은 우정, 10권은 다시 행복과 사색으로 돌아감.</li><li>따라서 이 책은 <strong>하나의 발전하는 탐구</strong>로 읽어야 하며, 모든 질문에 즉시 답이 주어질 것을 기대해서는 안 된다. 텍스트의 편집 역사도 불확실하며, 압축된 강의 노트 같은 문체로 전해져 왔다고 보는 것이 안전하다.</li></ul></li></ul><h2 id="윤리학과-정치학의-관계-—-왜-아리스토텔레스는-둘을-분리하지-않는가" tabindex="-1">윤리학과 정치학의 관계 — 왜 아리스토텔레스는 둘을 분리하지 않는가 <a class="header-anchor" href="#윤리학과-정치학의-관계-—-왜-아리스토텔레스는-둘을-분리하지-않는가" aria-label="Permalink to &quot;윤리학과 정치학의 관계 — 왜 아리스토텔레스는 둘을 분리하지 않는가&quot;">​</a></h2><ul><li>현대에는 윤리를 &quot;개인적인 것&quot;(나는 무엇을 해야 하는가), 정치를 &quot;공적인 것&quot;(제도를 어떻게 조직해야 좋은 시민을 기를 수 있는가)으로 나누는 경향이 있지만, 아리스토텔레스는 이 둘이 <strong>밀접히 연결</strong>되어 있다고 본다 — 인간은 혼자서 자신을 형성하지 않기 때문.</li><li><strong>성격은 결코 고립 속에서 형성되지 않는다.</strong> 언어를 타인의 발음·단어를 모방하며 배우듯, 감정 표현 방식(어릴 때는 즉각 표현하다가 성인이 되며 사회 규범에 맞춰 절제하는 법을 배움), 공동체가 무엇을 칭찬·비난하는지, 권위가 어떻게 작동하는지, 협력·경쟁·정직·공격성 중 무엇이 보상받는지를 모두 사회 속에서 배운다.</li><li>성격은 가족·학교·우정·직장·종교 전통·미디어·정치 제도, 그리고 <strong>디지털 플랫폼</strong>을 통해 형성된다.</li><li><strong>법의 역할</strong>: 법은 단지 잘못을 처벌하는 데 그치지 않고 <strong>반복되는 행동의 패턴을 구조화</strong>한다. 예: 교통 신호(반복적으로 멈추고 양보하며 공공 공간이 공유되어야 함을 체득), 차별금지법·접근성법(반복되는 제도적 행동을 변화시킴), 환경법(생산·소비 패턴을 바꿈). 법이 즉시 덕을 만들지는 않지만 <strong>무엇이 정상인지를 형성</strong>한다.</li><li>아리스토텔레스는 정치학을 <strong>건축학적 학문(architectonic discipline)</strong>이라 부른다 — 마치 총괄 건축가가 여러 일꾼과 활동을 하나의 큰 계획 아래 조정하듯, 정치는 의술(건강)·군사전략(승리)·경제활동(자원)·교육(능력 개발) 같은 여러 활동이 공유된 삶 안에서 어떻게 질서 지어져야 하는지를 결정해야 한다. <ul><li>사회는 경제적으로 생산적이면서도 정치적으로 부정의할 수 있고, 전쟁에서 이기면서도 시민에게 좋은 삶을 제공하지 못할 수 있으며, 우수한 대학을 가지면서도 많은 이들을 교육에서 배제할 수 있다.</li><li>개인에게 &quot;지적으로 뛰어나라&quot;고 요구하면서 교육 기회를 주지 않거나, &quot;부패에 맞서라&quot;면서 법적 보호를 주지 않거나, &quot;정치에 참여하라&quot;면서 실질적 권한을 주지 않는다면 — 개인의 책임만큼이나 <strong>사회적 조건</strong>이 중요하다는 것.</li></ul></li><li><strong>역사적 한계와 계승할 통찰의 분리</strong>: 아리스토텔레스의 정치공동체는 여성·노예·외국인·많은 노동자를 시민권에서 배제한, 포용적이지 않은 공동체였다 — 이 배제는 명백히 거부되어야 한다. 다만 &quot;정치 제도가 개인의 윤리적 성격을 형성하고, 개인의 윤리적 성격이 다시 정치 제도를 형성한다&quot;는 통찰 자체는, 평등·자유·민주적 참여·반(反)지배를 옹호하면서도 유지할 수 있는 가치가 있다.</li></ul><h3 id="현대적-적용-—-소셜미디어-플랫폼이라는-정치-공동체-아닌-정치-공동체" tabindex="-1">현대적 적용 — 소셜미디어 플랫폼이라는 &quot;정치 공동체 아닌 정치 공동체&quot; <a class="header-anchor" href="#현대적-적용-—-소셜미디어-플랫폼이라는-정치-공동체-아닌-정치-공동체" aria-label="Permalink to &quot;현대적 적용 — 소셜미디어 플랫폼이라는 &quot;정치 공동체 아닌 정치 공동체&quot;&quot;">​</a></h3><ul><li>소셜미디어 플랫폼은 도시국가는 아니지만, <strong>규칙과 반복되는 상호작용 패턴</strong>을 만든다 — 어떤 콘텐츠가 보이는지 결정하고, 특정 감정(분노·속도·확신·갈등·공개적 굴욕·지속적 자기과시)을 보상해 더 많은 관심을 끌도록 설계된다.</li><li>다른 사람의 삶과 내 삶을 비교하며 공허함·좌절을 느끼는 경험, 소셜미디어에서의 의견 표현 방식이 일상적·물리적 세계에서의 방식과 완전히 다른 현상 — 이런 구조가 <strong>주의(attention)와 감정의 습관</strong>에 영향을 미친다.</li><li>아리스토텔레스적 분석은 두 층위로 묻는다: (1) 개인 사용자가 책임감 있게 행동하는가, (2) <strong>플랫폼은 사용자를 어떤 유형의 사람·시민으로 훈련시키고 있는가.</strong> 즉각적 반응을 유도하는 플랫폼 설계 자체가 윤리적 질문이 된다 — 이것이 윤리·정치·기술이 완전히 분리될 수 없는 이유다.</li></ul><h3 id="ai와-목적론-—-수단과-목적의-구분" tabindex="-1">AI와 목적론 — 수단과 목적의 구분 <a class="header-anchor" href="#ai와-목적론-—-수단과-목적의-구분" aria-label="Permalink to &quot;AI와 목적론 — 수단과 목적의 구분&quot;">​</a></h3><ul><li>생성형 AI 업계 주요 인물들조차 AI로 인한 인류 멸종 가능성을 포함한 위험을 경고하고 있다. AI는 단순한 수단이 아니라 우리의 <strong>사고방식과 욕망하는 방식 자체를 형성</strong>하기 때문에 윤리적 문제를 제기한다.</li><li>아리스토텔레스의 목적론적(목적 지향적) 사고는 <strong>생태적 책임</strong>에 대한 성찰로도 확장된다 — 인간의 번영이 공동체와 정치적 헌신에 달려 있다면, 환경 파괴는 자연 생명뿐 아니라 인간 번영의 가능성 자체를 위협한다. 최근 환경철학·다종(multi-species) 윤리학은 번영을 인간만의 성취가 아니라 인간·동물·식물·생태계가 함께 번성할 수 있는 <strong>관계적 조건의 유지</strong>로 재해석하기도 한다.</li><li><strong>핵심 재확인</strong>: 아리스토텔레스의 질문은 &quot;사람들이 무엇을 원하는가&quot;가 아니라 <strong>&quot;궁극적으로 무엇이 진정 가치 있는가&quot;</strong>다. 수단과 목적의 구분은 우리 자신의 삶의 구조를 검토하게 만든다 — 일상의 추구가 진짜 최종 목적을 향하는지, 아니면 수단 자체가 목적지가 되어버렸는지.</li></ul><h2 id="습관화-habituation-도입-—-지적-탁월함-vs-성격의-탁월함" tabindex="-1">습관화(habituation) 도입 — 지적 탁월함 vs 성격의 탁월함 <a class="header-anchor" href="#습관화-habituation-도입-—-지적-탁월함-vs-성격의-탁월함" aria-label="Permalink to &quot;습관화(habituation) 도입 — 지적 탁월함 vs 성격의 탁월함&quot;">​</a></h2><p>지난 시간 &quot;행복은 덕에 따른 활동&quot;이라는 결론에서 남은 질문 — <strong>덕은 어떻게 획득되는가?</strong> — 을 풀기 위해 아리스토텔레스는 탁월함(arete, 아레테)을 두 종류로 나눈다.</p><ol><li><strong>지적 탁월함(intellectual excellence)</strong>: 이해·지식·추론·이론적 지혜·실천적 지혜 등을 포함하며, 주로 <strong>가르침·경험·시간</strong>을 통해 발전한다. 예: 논리적 방법을 지도받아 배우는 학생, 해부학을 교사·교과서로 배우는 의대생.</li><li><strong>성격의 탁월함(excellence of character)</strong>: 욕망·감정·쾌락·고통·선택·행동과 관련되며(예: 용기·절제·관대함·정의·적절한 분노), 주로 <strong>습관화</strong>를 통해 발달한다 — &quot;성격(ēthikē)&quot;이라는 단어 자체가 &quot;습관(ethos)&quot;의 변형어.</li></ol><p>(→ 위 &quot;2권 1장 원문 번역&quot; 참고: 돌이 위로 던져진다고 위로 움직이도록 습관화될 수 없듯, 성격의 탁월함은 본성에 의해 주어지는 것이 아니라 <strong>본성적으로 그것을 받아들일 수 있는 능력</strong>을 습관화를 통해 완성시키는 것. 감각처럼 능력이 먼저이고 발휘가 나중인 것과 달리, 덕은 <strong>먼저 활동에 관여함으로써</strong> 획득된다 — 건축가가 집을 지어봄으로써 건축가가 되고, 정의로운 일을 행함으로써 정의로워지는 방식.)</p><p><strong>두 탁월함은 독립적이지 않다.</strong> 용기는 (위험에 대한) 합리적 판단을 요구하고, 정의는 무엇이 옳고 그른지에 대한 이해를 요구한다 — 반대로 판단은 잘 형성된 욕망을 필요로 한다. 지능은 있지만 성격이 나쁜 사람은 그 지능을 타인을 조종하는 데 쓸 수 있고, 선의는 있지만 판단력이 부족한 사람은 심각한 해를 끼칠 수 있다. <strong>완전한 덕은 (성격의) 탁월함과 실천적 지혜 둘 다를 필요로 한다.</strong></p><ul><li>현대적 예: 매우 뛰어난 프로그래머가 극도로 효과적인 감시 시스템을 설계할 수 있다 — 기술적·지적 능력을 증명하지만, 그 능력만으로는 프라이버시·차별·자유에 관한 윤리적 질문에 답하지 못한다.</li></ul><h3 id="지적-탁월함이-가르침만으로-부족한-이유-—-경험과-시간" tabindex="-1">지적 탁월함이 가르침만으로 부족한 이유 — 경험과 시간 <a class="header-anchor" href="#지적-탁월함이-가르침만으로-부족한-이유-—-경험과-시간" aria-label="Permalink to &quot;지적 탁월함이 가르침만으로 부족한 이유 — 경험과 시간&quot;">​</a></h3><ul><li>&quot;<strong>주로(mostly)</strong>&quot;라는 단어가 중요하다 — 지적 탁월함이 교사에서 학생에게 정보처럼 단순히 전달될 수 있다는 뜻이 아니다. 가르침은 개념·설명·구별·논증 형식을 제공할 뿐, 그것을 실제로 사용해보는 연습이 필요하다.</li><li><strong>생성형 AI 시대의 함의</strong>: 학생이 AI로부터 훌륭한 답을 받을 수 있지만, AI가 제공한 답을 소유하는 것은 지적 탁월함을 갖추는 것과 다르다 — 스스로 논증을 독립적으로 설명하고, 거짓 전제를 발견하고, 증거를 평가하고, 모호성을 식별하고, 다른 사례에 개념을 적용하는 능력이 없다면 정보 접근 자체가 지적 탁월함은 아니다.</li><li><strong>경험·시간이 필요한 이유</strong>: 명제는 빨리 암기할 수 있어도 좋은 판단은 그렇지 않다. &quot;덕은 중용이다&quot;를 암기해도, 두려움·분노·쾌락·관대함·야망에 그 중용이 어떻게 구체적으로 적용되는지 이해하려면 경험이 필요하다 — 같은 침묵도 어떤 상황에선 비겁, 어떤 상황에선 신중함일 수 있듯 행위의 윤리적 의미는 맥락에 달려 있다. 나이가 많다고 저절로 지혜로운 것도 아니다 — 같은 실수를 30년간 반복할 수도 있다. <strong>경험이 지적으로 형성적이려면 반성(reflection)과 수정(correction)이 수반되어야 한다.</strong></li></ul><h2 id="소크라테스적-주지주의-비판-—-앎이-곧-행동을-보장하지-않는다" tabindex="-1">소크라테스적 주지주의 비판 — 앎이 곧 행동을 보장하지 않는다 <a class="header-anchor" href="#소크라테스적-주지주의-비판-—-앎이-곧-행동을-보장하지-않는다" aria-label="Permalink to &quot;소크라테스적 주지주의 비판 — 앎이 곧 행동을 보장하지 않는다&quot;">​</a></h2><p>아리스토텔레스의 이론은 <strong>소크라테스적 주지주의(Socratic intellectualism)</strong>에 대한 응답으로 읽을 수 있다.</p><ul><li>소크라테스의 두 테제: (1) <strong>덕은 곧 지식이다</strong>, (2) <strong>알면서 고의로 나쁜 일을 하는 사람은 없다</strong> — 잘못된 행동은 무지에서 비롯된다는 강한 버전의 주장.</li><li>아리스토텔레스는 이를 불완전하다고 본다. 지식이 존재해도 욕망이 다른 방향으로 움직일 수 있다 — 과음이 건강에 해롭다는 걸 알면서도 술을 끊지 못하거나, 거짓말이 잘못임을 알면서도 명예가 위협받으면 거짓말하는 경우. 이는 <strong>의지의 나약함(akrasia, weakness of will)</strong> 내지 자기통제력 부족과 연결된다.</li><li>아리스토텔레스가 지식을 경시하는 것은 아니다 — 다만 <strong>이성이 훈련된 욕망·감정과 결합되어야 한다</strong>는 것. 도덕 교육은 우리가 무엇을 즐기고, 무엇을 두려워하고, 무엇을 알아차리고, 무엇을 원하고, 무엇을 고통스러워하고, 무엇을 선택하는지에 영향을 미쳐야 한다. <ul><li>(플라톤도 교육·음악·사랑·신체 훈련·욕망의 통제를 중시했으므로, &quot;플라톤=지식만, 아리스토텔레스=실천만&quot;이라는 대비는 지나치게 단순하다. 더 정확한 지점은: 아리스토텔레스는 <strong>도덕적 지식만으로 완전한 덕이 충분하다는 생각을 명확히 거부</strong>하며, 윤리적 형성은 <strong>이해(understanding) + 습관화</strong> 둘 다를 요구한다는 것.)</li></ul></li></ul><h2 id="_2권-1장-정독-—-4가지-질문을-염두에-두고-읽기" tabindex="-1">2권 1장 정독 — 4가지 질문을 염두에 두고 읽기 <a class="header-anchor" href="#_2권-1장-정독-—-4가지-질문을-염두에-두고-읽기" aria-label="Permalink to &quot;2권 1장 정독 — 4가지 질문을 염두에 두고 읽기&quot;">​</a></h2><p>정독 전 제시된 4가지 질문:</p><ol><li>지적 교육과 성격 형성의 차이는 무엇인가?</li><li>왜 아리스토텔레스는 덕이 &quot;자연적이지도, 자연에 반하지도&quot; 않다고 말하는가?</li><li>누군가는 정의로운 사람이 되기 <strong>전에</strong> 정의로운 행동을 할 수 있는가?</li><li>어린 시절과 제도가 우리 성격을 형성한다면, 책임(responsibility)을 어떻게 이해해야 하는가?</li></ol><h3 id="지성-vs-성격-—-영혼의-두-차원" tabindex="-1">지성 vs 성격 — 영혼의 두 차원 <a class="header-anchor" href="#지성-vs-성격-—-영혼의-두-차원" aria-label="Permalink to &quot;지성 vs 성격 — 영혼의 두 차원&quot;">​</a></h3><ul><li>이 구분은 1권 말미에 제시된 영혼(soul)에 대한 설명을 발전시킨 것 — 영혼의 한 차원은 직접 추론하고, 다른 차원은 이성에 반응할 수 있는 욕망·감정을 포함한다.</li><li>지적 탁월함은 주로 잘 생각하고 추론하는 것, 성격의 탁월함은 주로 느끼고 선택하고 행동하는 것과 관련된다.</li></ul><h3 id="습관화의-기본-메커니즘" tabindex="-1">습관화의 기본 메커니즘 <a class="header-anchor" href="#습관화의-기본-메커니즘" aria-label="Permalink to &quot;습관화의 기본 메커니즘&quot;">​</a></h3><blockquote><p><strong>행동 → 반복 → 안정적 성향(disposition) → 미래의 행동</strong></p></blockquote><ul><li>진실을 반복해서 말하는 사람은 점차 정직이라는 안정적 성향을 발전시키고, 실수를 반복해서 숨기는 사람은 기만·부정직이라는 성향을 발전시킨다 — <strong>서로 다른 습관화가 좋은 성격과 나쁜 성격을 모두 만들 수 있다.</strong></li><li><strong>에티케(ēthikē, 성격·윤리적) / 에토스(ēthos, 성격 특성) / 에토스(ethos, 습관)</strong> 사이의 그리스어 언어유희 — 영어 번역은 이 말장난을 완전히 재현하지 못한다. 다만 어원적 유사성 자체가 이론을 증명하는 건 아니고, 이는 앞으로 아리스토텔레스가 예시를 통해 방어할 <strong>중심 논제를 소개</strong>하는 역할.</li><li><strong>철학적 질문</strong>: 습관은 단지 우리가 이미 그런 사람임을 표현하는 것인가, 아니면 우리가 될 사람을 만드는 데 일조하는가? 아리스토텔레스에게는 <strong>양방향 모두 작동한다</strong> — 성격이 행동을 형성하고, 반복된 행동이 성격을 형성한다.</li></ul><h3 id="본성에-의해서도-본성에-반해서도-아니다-—-돌-불-사례의-정밀-해석" tabindex="-1">&quot;본성에 의해서도, 본성에 반해서도 아니다&quot; — 돌/불 사례의 정밀 해석 <a class="header-anchor" href="#본성에-의해서도-본성에-반해서도-아니다-—-돌-불-사례의-정밀-해석" aria-label="Permalink to &quot;&quot;본성에 의해서도, 본성에 반해서도 아니다&quot; — 돌/불 사례의 정밀 해석&quot;">​</a></h3><ul><li>우리는 완성된 도덕적 덕을 갖고 태어나지 않는다 — 완전히 정의롭거나 완전히 용감하거나 완전히 절제된 상태로 태어나지 않는다. 다만 서로 다른 <strong>타고난 기질(temperament)</strong>은 가질 수 있다 — 그러나 기질은 아직 덕이 아니다. 자연적으로 유능해 보이는 사람도 무모해질 수 있고, 자연적으로 정의로워 보이는 사람도 비겁해질 수 있다 — <strong>기질은 출발점일 뿐 완성된 덕이 아니다.</strong> 아리스토텔레스는 &quot;어떤 사람은 그냥 이기적으로/비도덕적으로 태어난다&quot;는 단순한 도덕적 결정론을 거부한다 — 교육·제도·관습·사회적 관계 모두가 성격 형성에 관여한다.</li><li><strong>돌(→ 원문에서는 &quot;태양&quot;으로 오역되어 자막에 등장했으나, 본문은 명백히 돌stone 사례) 사례</strong>: 본성적으로 고정된 경향(중력에 의해 아래로 움직임)은 아무리 반복(만 번 위로 던짐)해도 반대 방향으로 바뀌지 않는다 — 돌은 기억·학습·해석·성향 획득을 하지 않기 때문. <strong>반면 인간은 행동 패턴을 내면화할 수 있다.</strong><ul><li>이 인간의 사회적 형성 능력은 <strong>윤리적으로 양가적(ambivalent)</strong>이다 — 좋은 교육뿐 아니라 선전·강압·트라우마·조작을 통해서도 형성될 수 있다. 그래서 &quot;습관화가 언제 도덕 교육이 되고, 언제 타인에 대한 지배가 되는가&quot;라는 질문이 따라온다.</li></ul></li><li><strong>불(fire) 사례</strong>도 같은 논리 — 아리스토텔레스의 고대 물리학에서 불은 본성상 위로 움직인다고 보았는데(이 물리학 자체를 받아들일 필요는 없음), 요점은 <strong>본성으로 고정된 것은 훈련으로 반대 경향을 획득할 수 없다</strong>는 것.</li><li><strong>핵심 문장 — &quot;본성에 의해서도, 본성에 반해서도 아니다&quot;</strong>: 아리스토텔레스는 두 입장을 모두 거부한다. (1) 사람은 본래 완전히 선하거나 악하다는 입장, (2) 윤리적 형성이 인간 본성에 반한다는 입장. 덕은 본성에 의해 이미 완성된 것도 아니지만, 인간 본성에 낯선 것도 아니다 — 이는 <strong>엄격한 자연 결정론</strong>과 <strong>무제한적 사회 구성 이론</strong> 사이의 중간 입장이다. <ul><li>우리는 본성적으로 그것들을 받아들일 능력을 지니며, 본성에 의해 완성에 이르게 된다 — 인간은 학습하고, 모방하고, 이유에 반응하고, 행동을 재고안·수정하고, 욕구와 습관을 형성할 수 있다. <strong>다만 자연적 능력이 특정 결과를 결정하지는 않는다</strong>: 자신감은 용기로도, 무모함으로도 발전할 수 있고, 쾌락을 느끼는 능력은 절제로도, 자기탐닉으로도 발전할 수 있다. <strong>자연은 능력(capacity)을 제공할 뿐, 미리 정해진 도덕적 결과를 제공하지 않는다.</strong></li></ul></li></ul><h3 id="내가-가졌던-의문-돌-사례-재확인" tabindex="-1">내가 가졌던 의문 (돌 사례 재확인) <a class="header-anchor" href="#내가-가졌던-의문-돌-사례-재확인" aria-label="Permalink to &quot;내가 가졌던 의문 (돌 사례 재확인)&quot;">​</a></h3><p>위 &quot;2권 1장 원문 번역&quot; 섹션에서 기록한 의문 — &quot;돌이 본성이라 습관화 불가능하다면, 성격도 본성이면 영원히 안 바뀌는 것 아닌가?&quot; — 은 정확히 이 대목(2권 1장, &quot;본성에 의해서도 반해서도 아니다&quot;)에 대한 핵심 통찰이었다. 요약: 돌 사례는 귀류법적 대조 장치이고, 인간 성격이 습관화로 실제 바뀐다는 관찰 자체가 &quot;성격은 돌처럼 고정된 본성이 아니다&quot;라는 결론의 근거다.</p><p>이 지점에서 강의는 다음 시간(중용·선택과 실천적 지혜)으로 이어진다.</p><hr><p><em>출처: KNU Canvas TransLive 실시간 통번역 자막(2026-09-18, 윤리학 001분반 3주차, 윤지영 교수) 및 강의 PPT(Nicomachean Ethics Book II, Bartlett &amp; Collins 역)를 바탕으로 직접 재구성한 정리 노트. 원문 자막 전문은 <a href="./Raw-Transcripts/2026-09-18_week3.html">Raw-Transcripts 폴더</a>에 별도 보관.</em></p>',47)])])}const p=o(i,[["render",s]]);export{c as __pageData,p as default};
